contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public {
        require(recipient != address(0));
        // First attempt (may succeed or revert depending on funding); capture outcome.
        bool reverted1;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        // Second attempt for the same recipient.
        bool reverted2;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        // If the first call succeeded, the bonus was claimed and the second call must revert.
        // If the first call reverted (e.g. insufficient funds), the second reverts for the same reason.
        assert(!reverted1 || reverted2);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount) public payable {
        require(true);
        require(address(this).balance >= amount);
        c.withdrawReward(address(this));
        c.getFirstWithdrawalBonus{value: amount}(recipient);
        c.withdrawReward(address(this));
        uint delta = address(this).balance - beforeBalance;
        assert(delta == 100 || !recipientPaid);
    }
    uint beforeBalance;
    bool recipientPaid;
    receive() external payable {
        if (address(c).balance == 0 && msg.value == 100) { recipientPaid = true; }
        else { beforeBalance = address(this).balance - msg.value; }
    }
}

